    facet_grid(hospital ~ period_lab, switch = "y") +
    scale_fill_manual(values = c(`FALSE` = "grey40", `TRUE` = "#D55E00"), guide = "none") +
    scale_x_continuous(limits = c(0, xmax), breaks = scales::breaks_pretty(3),
                       expand = expansion(mult = c(0, 0.08))) +
    labs(x = if (x_axis) "Number of samples" else NULL, y = y_lab) +
    theme_bw() +
    theme(panel.grid.minor = element_blank(),
          strip.placement  = "outside",
          axis.text.x      = if (x_axis) element_text() else element_blank(),
          axis.ticks.x     = if (x_axis) element_line() else element_blank())
}

