# ===========================================================================
# SUMMARY VALUES FOR THE PANEL A DESCRIPTION
# ===========================================================================

pp  &lt;- \(x) sprintf("%.1f", 100 * x)      # proportion as a percentage
ppd &lt;- \(x) sprintf("%+.1f", 100 * x)     # change in percentage points

wk_first &lt;- min(lines_region$week)
wk_last  &lt;- max(lines_region$week)

c(as.character(wk_first), as.character(wk_last))   # the period being described

# ---- 1. Start, end, and change for every region and series ----------------

ends &lt;- lines_region |&gt;
  filter(week %in% c(wk_first, wk_last)) |&gt;
  mutate(point = if_else(week == wk_first, "start", "end")) |&gt;
  select(series, region, point, value) |&gt;
  pivot_wider(names_from = point, values_from = value) |&gt;
  mutate(change_pp = 100 * (end - start)) |&gt;
  arrange(series, desc(end))

ends |&gt; print(n = Inf)

# ---- 2. Leading and trailing region, and the spread between them ----------

extremes &lt;- lines_region |&gt;
  filter(week %in% c(wk_first, wk_last)) |&gt;
  mutate(point = factor(if_else(week == wk_first, "Start", "End"),
                        levels = c("Start", "End"))) |&gt;
  summarise(
    highest   = as.character(region[which.max(value)]),
    high_val  = max(value),
    lowest    = as.character(region[which.min(value)]),
    low_val   = min(value),
    spread_pp = 100 * (max(value) - min(value)),
    .by = c(series, point)
  ) |&gt;
  arrange(series, point)

extremes |&gt; print(n = Inf)

# did the ranking of regions change between start and end?
lines_region |&gt;
  filter(week %in% c(wk_first, wk_last)) |&gt;
  mutate(point = if_else(week == wk_first, "start", "end"),
         rk    = rank(-value), .by = c(series, week)) |&gt;
  select(series, region, point, rk) |&gt;
  pivot_wider(names_from = point, values_from = rk) |&gt;
  filter(start != end) |&gt;
  print(n = Inf)

# ---- 3. EVC with its uncertainty interval --------------------------------

evc_ci &lt;- rib_region |&gt;
  filter(week %in% c(wk_first, wk_last)) |&gt;
  left_join(lines_region |&gt;
              filter(series == x_labels[["EVC"]]) |&gt;
              select(week, group, evc = value),
            by = c("week", "group")) |&gt;
  mutate(point    = factor(if_else(week == wk_first, "Start", "End"),
                           levels = c("Start", "End")),
         width_pp = 100 * (evc_hi - evc_lo),
         lab      = sprintf("%s%% (%s to %s%%)", pp(evc), pp(evc_lo), pp(evc_hi))) |&gt;
  select(region, point, evc, evc_lo, evc_hi, width_pp, lab) |&gt;
  arrange(point, desc(evc))

evc_ci |&gt; print(n = Inf)

# band width across the whole period: all regions share the same draws, so
# this is VE-parameter uncertainty, not between-region precision
rib_region |&gt;
  summarise(width_min = 100 * min(evc_hi - evc_lo),
            width_med = 100 * median(evc_hi - evc_lo),
            width_max = 100 * max(evc_hi - evc_lo))

# ---- 4. Gap between MCV1 coverage and estimated immunity -----------------
# The vertical distance between the two lines is primary vaccine failure
# plus waning, expressed in percentage points.

gap &lt;- lines_region |&gt;
  filter(series %in% unname(x_labels[c("Dose 1", "EVC")])) |&gt;
  select(week, region, series, value) |&gt;
  pivot_wider(names_from = series, values_from = value) |&gt;
  rename(mcv1 = !!x_labels[["Dose 1"]], evc = !!x_labels[["EVC"]]) |&gt;
  mutate(gap_pp = 100 * (mcv1 - evc))

gap |&gt;
  summarise(gap_start = gap_pp[which.min(week)],
            gap_end   = gap_pp[which.max(week)],
            gap_min   = min(gap_pp),
            gap_max   = max(gap_pp),
            .by = region) |&gt;
  print(n = Inf)

# ---- 5. Largest week-on-week step, e.g. the early-2024 jump --------------

lines_region |&gt;
  arrange(region, series, week) |&gt;
  mutate(step_pp = 100 * (value - lag(value)), .by = c(region, series)) |&gt;
  slice_max(step_pp, n = 1, by = c(region, series)) |&gt;
  select(series, region, week, step_pp) |&gt;
  arrange(series, desc(step_pp)) |&gt;
  print(n = Inf)

# ---- 6. Sentence-ready strings -------------------------------------------

ends |&gt;
  mutate(txt = sprintf("%s, %s: %s%% to %s%% (%s pp)",
                       series, region, pp(start), pp(end), ppd(end - start))) |&gt;
  pull(txt) |&gt;
  writeLines()

evc_ci |&gt;
  filter(point == "End") |&gt;
  mutate(txt = sprintf("%s: EVC %s", region, lab)) |&gt;
  pull(txt) |&gt;
  writeLines()

Values sero vs cov

# ===========================================================================
# SUMMARY VALUES FOR THE PANEL C DESCRIPTION
# ===========================================================================

pp &lt;- \(x) sprintf("%.1f", 100 * x)

# ---- 1. Seroprevalence by region, with sample sizes -----------------------
# Same sera for MCV1 and EVC (9-59 mo); MCV2 uses 18-59 mo, so its
# seroprevalence and n differ.

scat |&gt;
  select(metric, region, x_pos, n_sero, sero, sero_lo, sero_hi) |&gt;
  mutate(lab = sprintf("%s%% (%s to %s%%), %d/%d",
                       pp(sero), pp(sero_lo), pp(sero_hi), x_pos, n_sero)) |&gt;
  arrange(metric, desc(sero)) |&gt;
  print(n = Inf)

# range across regions, per age window
scat |&gt;
  summarise(n_regions = n(),
            n_sera    = sum(n_sero),
            sero_min  = min(sero), sero_max = max(sero),
            reg_min   = as.character(region[which.min(sero)]),
            reg_max   = as.character(region[which.max(sero)]),
            .by = metric) |&gt;
  print(n = Inf)

# widest and narrowest confidence intervals, which drive how much the
# scatter can be read at all
scat |&gt;
  mutate(ci_pp = 100 * (sero_hi - sero_lo)) |&gt;
  slice_max(ci_pp, n = 1, by = metric) |&gt;
  select(metric, region, n_sero, sero, ci_pp) |&gt;
  print(n = Inf)

# ---- 2. The x metrics: period value and temporal range -------------------

scat |&gt;
  mutate(lab = sprintf("%s%% (range %s to %s%%)", pp(x), pp(x_lo), pp(x_hi))) |&gt;
  select(metric, region, x, x_lo, x_hi, lab) |&gt;
  arrange(metric, desc(x)) |&gt;
  print(n = Inf)

scat |&gt;
  summarise(x_min = min(x), x_max = max(x),
            spread_pp = 100 * (max(x) - min(x)),
            reg_min = as.character(region[which.min(x)]),
            reg_max = as.character(region[which.max(x)]),
            .by = metric) |&gt;
  print(n = Inf)

# EVC parameter interval, which only the EVC panel carries
scat |&gt;
  filter(!is.na(xu_lo)) |&gt;
  mutate(u_pp = 100 * (xu_hi - xu_lo)) |&gt;
  select(metric, region, x, xu_lo, xu_hi, u_pp) |&gt;
  print(n = Inf)

# ---- 3. The gap: how far every point sits below the 1:1 line -------------
# This is the dominant feature of panel C and the number to lead with.

scat |&gt;
  mutate(gap_pp = 100 * (x - sero)) |&gt;
  summarise(gap_med = median(gap_pp),
            gap_min = min(gap_pp), gap_max = max(gap_pp),
            n_above = sum(gap_pp &lt; 0),          # regions above the 1:1 line
            .by = metric) |&gt;
  print(n = Inf)

# per region, for the metric-specific sentences
scat |&gt;
  mutate(gap_pp = 100 * (x - sero)) |&gt;
  select(metric, region, x, sero, gap_pp) |&gt;
  arrange(metric, desc(gap_pp)) |&gt;
  print(n = Inf)

# does any region's seroprevalence CI reach its x value?
scat |&gt;
  filter(sero_hi &gt;= x) |&gt;
  select(metric, region, x, sero, sero_hi) |&gt;
  print(n = Inf)

# ---- 4. Do the two axes rank the regions the same way? -------------------
# Ranking agreement is the descriptive version of the correlation, and is
# more honest than a p-value at n = 5.

scat |&gt;
  mutate(rk_x = rank(-x), rk_y = rank(-sero), .by = metric) |&gt;
  select(metric, region, rk_x, rk_y) |&gt;
  arrange(metric, rk_x) |&gt;
  print(n = Inf)

scat |&gt;
  summarise(rho = cor(x, sero, method = "spearman"),
            n_concordant = sum(rank(-x) == rank(-sero)),
            .by = metric) |&gt;
  print(n = Inf)

# ---- 5. Sentence-ready strings -------------------------------------------

scat |&gt;
  filter(metric == x_labels[["EVC"]]) |&gt;
  mutate(txt = sprintf("%s: EVC %s%%, seroprevalence %s%% (%s to %s%%), gap %.1f pp",
                       region, pp(x), pp(sero), pp(sero_lo), pp(sero_hi),
                       100 * (x - sero))) |&gt;
  arrange(desc(x)) |&gt;
  pull(txt) |&gt;
  writeLines()

